function animate(){cancelAnimationFrame(loop);const tick=()=>{repaint();loop=requestAnimationFrame(tick);};tick();}
function setView(view){$$('.view').forEach(e=>e.hidden=e.id!==view+'-view');$$('.sidebar [data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===view));if(view==='gallery')refreshGallery();window.scrollTo({top:0,behavior:'smooth'});}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
const sliderSpecs=[['exposure','Exposição',-2,2,.1,'EV'],['contrast','Contraste',-60,60,1,''],['saturation','Saturação',-100,100,1,''],['temperature','Temperatura',-80,80,1,''],['grain','Granulação',0,60,1,''],['vignette','Vinheta',0,70,1,''],['leak','Vazamento de luz',0,100,1,'']];
$('#sliders').innerHTML=sliderSpecs.map(([id,name,min,max,step,unit])=>`<label class="slider" for="${id}"><div><span>${name}</span><output id="${id}-value"></output></div><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" aria-label="${name}"></label>`).join('');
for(const [id,,, , ,unit]of sliderSpecs){$('#'+id).oninput=e=>{settings[id]=+e.target.value;$('#'+id+'-value').textContent=settings[id]+(unit?' '+unit:'');persist();repaint();};}
function sync(){for(const [id,,,,,unit]of sliderSpecs){$('#'+id).value=settings[id];$('#'+id+'-value').textContent=settings[id]+(unit?' '+unit:'');}for(const id of ['ratio','frame','quality','zoom'])$('#'+id).value=settings[id];for(const id of ['timestamp','mirror','negative','sound'])$('#'+id).checked=settings[id];$('#timer small').textContent=settings.timer+'s';$('#timer').dataset.seconds=settings.timer||'';$('#grid').classList.toggle('on',settings.grid);$('.grid-overlay').hidden=!settings.grid;$('#ratio-label').textContent=settings.ratio==='original'?'ORIGINAL':settings.ratio;updateCamera();}
for(const id of ['ratio','frame','quality','zoom'])$('#'+id).oninput=e=>{if(recorder?.state==='recording'&&['ratio','frame','quality'].includes(id)){e.target.value=settings[id];return toast('Ajuste o formato depois de encerrar a gravação.');}settings[id]=['zoom','quality'].includes(id)?+e.target.value:e.target.value;persist();sync();repaint();};
for(const id of ['timestamp','mirror','negative','sound'])$('#'+id).onchange=e=>{settings[id]=e.target.checked;persist();repaint();};
$('#grid').onclick=()=>{settings.grid=!settings.grid;persist();sync();};$('#timer').onclick=()=>{settings.timer=[0,3,10][([0,3,10].indexOf(settings.timer)+1)%3];persist();sync();};
$('#reset').onclick=()=>{const camera=settings.camera;settings={...settings,...Object.fromEntries(sliderSpecs.map(([k])=>[k,defaults[k]])),camera,zoom:1};persist();sync();repaint();};
function illustration(c){return `<div class="camera-illustration" style="filter:hue-rotate(${c.filter[3]*8}deg)"><div class="cam-flash"></div><div class="cam-lens"></div><span>${c.name.toUpperCase()}</span></div>`;}
function chooseCamera(id){if(recorder?.state==='recording')return toast('Encerre a gravação para trocar de câmera.');halfFrame=null;settings.camera=id;const c=cameras.find(c=>c.id===id);settings.frame=c.frame||'none';if(id==='instsq')settings.ratio='1:1';persist();sync();repaint();$('#cameras-dialog').close();if(c.family==='Vídeo')setMode('video');else setMode('photo');window.dispatchEvent(new CustomEvent('camera-changed'));}
function updateCamera(){const c=cameras.find(c=>c.id===settings.camera)||cameras[0];$('#selected-name').textContent=c.name;$('#selected-family').textContent=c.family.toUpperCase();$('#camera-description').textContent=c.desc;$('#art-label').textContent=c.name.toUpperCase();$('#camera-art').style.filter=`hue-rotate(${c.filter[3]*8}deg)`;$('#vf-camera').textContent=c.name.toUpperCase();$('#quick-cameras').innerHTML=['classic','ccdr','instc','dblack'].map(id=>{const x=cameras.find(c=>c.id===id);return `<button data-camera="${id}" class="${id===c.id?'active':''}">${x.name}</button>`;}).join('');$$('[data-camera]').forEach(b=>b.onclick=()=>chooseCamera(b.dataset.camera));}
function catalog(family='Todas'){$('#camera-catalog').innerHTML=cameras.filter(c=>family==='Todas'||c.family===family).map(c=>`<button class="camera-card ${c.id===settings.camera?'active':''}" data-camera="${c.id}">${illustration(c)}<small>${c.family.toUpperCase()}</small><strong>${c.name}</strong><p>${c.desc}</p></button>`).join('');$$('[data-camera]').forEach(b=>b.onclick=()=>chooseCamera(b.dataset.camera));}
$('#camera-picker').onclick=()=>{catalog();$('#cameras-dialog').showModal();};$$('[data-family]').forEach(b=>b.onclick=()=>{$$('[data-family]').forEach(x=>x.classList.toggle('active',x===b));catalog(b.dataset.family);});
$('#settings-open').onclick=()=>$('#settings-dialog').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function stopSource(){if(recorder?.state==='recording')recorder.stop();cancelAnimationFrame(loop);stream?.getTracks().forEach(t=>t.stop());stream=null;video.pause();video.srcObject=null;video.removeAttribute('src');if(sourceURL){URL.revokeObjectURL(sourceURL);sourceURL=null;}front=false;overlay=null;}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia)return toast('A câmera precisa de HTTPS ou localhost. Você também pode importar uma foto.');if(recorder?.state==='recording')return toast('Encerre a gravação antes de trocar a câmera.');try{const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:desiredFacing,width:{ideal:1920},height:{ideal:1440}},audio:false});stopSource();stream=next;front=desiredFacing==='user';video.srcObject=stream;await video.play();source=video;sourceKind='camera';$('#welcome').hidden=true;$('#source-label').textContent=front?'CÂMERA FRONTAL':'CÂMERA TRASEIRA';$('#camera-status').textContent='CÂMERA ATIVA';animate();}catch(e){toast(e.name==='NotAllowedError'?'Permita o acesso à câmera nas configurações do navegador, ou importe uma foto.':e.name==='NotFoundError'?'Nenhuma câmera encontrada. Importe uma foto para continuar.':'Não foi possível abrir a câmera. Confira se outro app está usando-a.');}}
let desiredFacing='environment';$('#start-camera').onclick=startCamera;$('#flip').onclick=()=>{desiredFacing=desiredFacing==='environment'?'user':'environment';startCamera();};
$('#flash').onclick=async()=>{const track=stream?.getVideoTracks()[0];if(!track?.getCapabilities?.().torch)return toast('A lanterna não está disponível nesta câmera ou navegador.');const enabled=!$('#flash').classList.contains('on');try{await track.applyConstraints({advanced:[{torch:enabled}]});$('#flash').classList.toggle('on',enabled);}catch(e){fail(e);}};
function imageFrom(blob){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(blob);img.onload=()=>{URL.revokeObjectURL(url);resolve(img);};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Formato de imagem não suportado. Use JPEG, PNG ou WebP.'));};img.src=url;});}
let originalBlob=null,halfFrame=null;
async function importFile(file){if(!file)return;if(recorder?.state==='recording')return toast('Encerre a gravação antes de importar.');try{if(file.type.startsWith('video/')){stopSource();originalBlob=file;sourceURL=URL.createObjectURL(file);video.src=sourceURL;video.loop=true;await video.play();source=video;sourceKind='video';setMode('video');animate();toast('Vídeo carregado. Toque em gravar para exportar com os efeitos.');}else{const img=await imageFrom(file);stopSource();originalBlob=file;source=img;sourceKind='image';setMode('photo');repaint();}$('#welcome').hidden=true;$('#source-label').textContent='MATERIAL IMPORTADO';$('#camera-status').textContent='PRONTO PARA REVELAR';}catch(e){fail(e);}}
$('#file-input').onchange=e=>{importFile(e.target.files[0]);e.target.value='';};for(const id of ['import-top','import-bottom'])$('#'+id).onclick=()=>$('#file-input').click();
async function demo(){const img=new Image();img.src='assets/demo.svg';await img.decode();stopSource();source=img;sourceKind='demo';originalBlob=await (await fetch('assets/demo.svg')).blob();repaint();}
$('#demo').onclick=async()=>{await demo();$('#welcome').hidden=true;toast('Imagem de demonstração. Ajuste os efeitos e revele.');};
function setMode(value){if(recorder?.state==='recording')return toast('Encerre a gravação para mudar o modo.');mode=value;overlay=null;halfFrame=null;$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===value));$('#shutter-label').textContent=value==='video'?'GRAVAR':value==='double'?'1ª EXPOSIÇÃO':'CAPTURAR';repaint();}
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
async function countdown(){if(settings.timer)for(let n=settings.timer;n>0;n--){$('#countdown').hidden=false;$('#countdown').textContent=n;await new Promise(r=>setTimeout(r,1000));}$('#countdown').hidden=true;}
function clickSound(){if(!settings.sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),g=ctx.createGain();osc.connect(g);g.connect(ctx.destination);osc.frequency.value=220;g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.06);osc.start();osc.stop(ctx.currentTime+.07);osc.onended=()=>ctx.close();}catch{}}
async function storeOutput(blob,type='photo',negative=null,recipe=settings){const item={id:crypto.randomUUID(),created:Date.now(),blob,type,negative:settings.negative?negative:null,settings:{...recipe},camera:cameras.find(c=>c.id===recipe.camera)?.name||'Colagem',favorite:false};await saveMedia(item);library=await allMedia();$('#album-count').textContent=library.length;if(type==='photo'){const u=URL.createObjectURL(blob);$('#last-photo').style.backgroundImage=`url(${u})`;$('#last-photo').textContent='';setTimeout(()=>URL.revokeObjectURL(u),10000);}toast(type==='video'?'Vídeo salvo no seu álbum.':'Memória revelada e salva no álbum.');return item;}
async function capture(forcePhoto=false){if(busy)return;if(!source)return toast('Abra a câmera ou importe uma foto.');if(mode==='video'&&!forcePhoto)return toggleRecording();busy=true;$('#shutter').disabled=true;$('#save-photo').disabled=true;try{await countdown();let out=document.createElement('canvas');render(out,source,settings,{mirror:front&&settings.mirror&&sourceKind==='camera',overlay});if(settings.camera==='dhalf'&&mode==='photo'&&!forcePhoto){if(!halfFrame){halfFrame=out;$('#shutter-label').textContent='2º QUADRO';toast('Primeiro quadro pronto. Fotografe o segundo.');return;}const joined=document.createElement('canvas');joined.width=out.width*2+16;joined.height=out.height;const jc=joined.getContext('2d');jc.fillStyle='#eee9dc';jc.fillRect(0,0,joined.width,joined.height);jc.drawImage(halfFrame,0,0,out.width,out.height);jc.drawImage(out,out.width+16,0);out=joined;halfFrame=null;}if(mode==='double'&&!overlay&&!forcePhoto){overlay=out;$('#shutter-label').textContent='2ª EXPOSIÇÃO';toast('Primeira exposição pronta. Mude o enquadramento e capture novamente.');repaint();return;}let negative=originalBlob;if(source===video){const raw=document.createElement('canvas');render(raw,source,{...defaults,camera:'original',grain:0,vignette:0,quality:settings.quality,ratio:'original'});negative=await blobFromCanvas(raw);}await storeOutput(await blobFromCanvas(out),'photo',mode==='double'||settings.camera==='dhalf'?null:negative);overlay=null;clickSound();document.body.classList.add('capturing');setTimeout(()=>document.body.classList.remove('capturing'),100);$('#shutter-label').textContent=mode==='double'?'1ª EXPOSIÇÃO':'CAPTURAR';}catch(e){fail(e);}finally{busy=false;$('#shutter').disabled=false;$('#save-photo').disabled=false;}}
$('#shutter').onclick=()=>capture();$('#save-photo').onclick=()=>capture(true);$('#last-photo').onclick=()=>setView('gallery');
async function toggleRecording(){if(recorder?.state==='recording'){recorder.stop();return;}if(typeof MediaRecorder==='undefined'||!preview.captureStream)return toast('Gravação não suportada neste navegador. Use Chrome ou Edge atualizados.');if(sourceKind!=='camera'&&sourceKind!=='video')return toast('Abra a câmera ou importe um vídeo para gravar.');let audioStream=null;try{await countdown();if(sourceKind==='camera'){try{audioStream=await navigator.mediaDevices.getUserMedia({audio:true});}catch{toast('Sem acesso ao microfone. O vídeo será gravado sem áudio.');}}else if(video.captureStream){audioStream=video.captureStream();}const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recordStream=preview.captureStream(30);audioStream?.getAudioTracks().forEach(t=>recordStream.addTrack(t));recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:{});const chunks=[],recipe={...settings};recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{clearInterval(recordInterval);$('#record-time').textContent='● FILM SIMULATION';$('#shutter').classList.remove('recording');$('#shutter-label').textContent='GRAVAR';recordStream?.getTracks().forEach(t=>t.stop());if(sourceKind==='camera')audioStream?.getTracks().forEach(t=>t.stop());try{await storeOutput(new Blob(chunks,{type:recorder.mimeType}),'video',null,recipe);}catch(e){fail(e);}recorder=null;};recorder.onerror=e=>{fail(e.error||new Error('Erro na gravação.'));if(recorder.state!=='inactive')recorder.stop();};recorder.start(1000);recordStart=Date.now();$('#shutter').classList.add('recording');$('#shutter-label').textContent='PARAR';recordInterval=setInterval(()=>{const s=Math.floor((Date.now()-recordStart)/1000);$('#record-time').textContent=`● REC ${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;},300);toast('Gravando. Toque novamente para encerrar.');}catch(e){audioStream?.getTracks().forEach(t=>t.stop());fail(e);}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function fileName(item){return `dazz-${new Date(item.created).toISOString().replace(/[:.]/g,'-')}.${item.type==='video'?(item.blob.type.includes('mp4')?'mp4':'webm'):'jpg'}`;}
async function refreshGallery(){try{library=await allMedia();$('#album-count').textContent=library.length;mediaURLs.forEach(URL.revokeObjectURL);mediaURLs=[];const visible=library.filter(i=>galleryFilter==='all'||(galleryFilter==='favorites'?i.favorite:i.type===galleryFilter));$('#gallery').replaceChildren();$('#gallery-empty').hidden=visible.length>0;$('#gallery-total').textContent=visible.length+' memórias';for(const item of visible){const url=URL.createObjectURL(item.blob);mediaURLs.push(url);const button=document.createElement('button');button.className='gallery-card';button.setAttribute('aria-label',`${item.camera}, ${new Date(item.created).toLocaleDateString('pt-BR')}`);const media=document.createElement(item.type==='video'?'video':'img');media.src=url;if(item.type==='video'){media.muted=true;media.preload='metadata';}else media.alt=item.camera;const caption=document.createElement('div');caption.className='caption';caption.textContent=`${item.favorite?'♥ ':''}${item.camera.toUpperCase()} · ${new Date(item.created).toLocaleDateString('pt-BR')}${item.type==='video'?' ▶':''}`;button.append(media,caption);button.onclick=()=>openMedia(item);$('#gallery').append(button);}}catch(e){fail(e);}}
$$('[data-gallery-filter]').forEach(b=>b.onclick=()=>{galleryFilter=b.dataset.galleryFilter;$$('[data-gallery-filter]').forEach(x=>x.classList.toggle('active',x===b));refreshGallery();});
let detailURL=null;function openMedia(item){selectedMedia=item;const media=document.createElement(item.type==='video'?'video':'img');if(detailURL)URL.revokeObjectURL(detailURL);detailURL=URL.createObjectURL(item.blob);media.src=detailURL;if(item.type==='video'){media.controls=true;media.playsInline=true;}else media.alt=item.camera;$('#media-content').replaceChildren(media);$('#media-title').textContent=item.camera+' / '+new Date(item.created).toLocaleDateString('pt-BR');$('#media-favorite').textContent=item.favorite?'♥ Favorito':'♡ Favoritar';$('#media-edit').hidden=!item.negative;$('#media-dialog').showModal();}
$('#media-dialog').addEventListener('close',()=>{$('#media-content video')?.pause();if(detailURL){URL.revokeObjectURL(detailURL);detailURL=null;}});
$('#media-favorite').onclick=async()=>{try{selectedMedia.favorite=!selectedMedia.favorite;await saveMedia(selectedMedia);$('#media-favorite').textContent=selectedMedia.favorite?'♥ Favorito':'♡ Favoritar';refreshGallery();}catch(e){fail(e);}};
$('#media-download').onclick=()=>download(selectedMedia.blob,fileName(selectedMedia));$('#media-delete').onclick=async()=>{if(!confirm('Excluir esta memória do álbum local?'))return;try{await removeMedia(selectedMedia.id);$('#media-dialog').close();await refreshGallery();toast('Memória excluída.');}catch(e){fail(e);}};
$('#media-edit').onclick=async()=>{const item=selectedMedia;await importFile(item.negative);settings={...settings,...item.settings};sync();repaint();$('#media-dialog').close();setView('camera');toast('Negativo aberto. A nova revelação será salva como outra foto.');};
$('#clear-album').onclick=async()=>{if(!confirm('Apagar todas as fotos e vídeos deste navegador? Exporte antes: esta ação não pode ser desfeita.'))return;try{await clearMedia();await refreshGallery();$('#last-photo').style.backgroundImage='';$('#last-photo').textContent='▧';toast('Álbum local apagado.');}catch(e){fail(e);}};
// Portable uncompressed ZIP, avoiding repeated browser download permission prompts.
function crc32(bytes){let crc=-1;for(const v of bytes){crc^=v;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^-1)>>>0;}
async function zipMedia(items){let offset=0;const local=[],central=[];for(const [i,item]of items.entries()){const data=new Uint8Array(await item.blob.arrayBuffer()),name=new TextEncoder().encode(`${i+1}-${fileName(item)}`),crc=crc32(data),h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);local.push(h,data);const ch=new Uint8Array(46+name.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);ch.set(name,46);central.push(ch);offset+=h.length+data.length;}const end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,items.length,true);ev.setUint16(10,items.length,true);ev.setUint32(12,central.reduce((n,c)=>n+c.length,0),true);ev.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'});}
$('#export-all').onclick=async()=>{try{const items=await allMedia();if(!items.length)return toast('O álbum ainda está vazio.');$('#export-all').disabled=true;toast('Preparando seu álbum…');download(await zipMedia(items),'dazz-album.zip');}catch(e){fail(e);}finally{$('#export-all').disabled=false;}};
$('#collage-import').onclick=()=>$('#collage-input').click();$('#collage-input').onchange=async e=>{try{for(const file of [...e.target.files]){if(collage.length>=6){toast('A colagem comporta até 6 fotos.');break;}const img=await imageFrom(file);collage.push({img,url:URL.createObjectURL(file)});}drawCollage();}catch(e){fail(e);}e.target.value='';};
function drawCollage(){const c=$('#collage-canvas'),ctx=c.getContext('2d'),layout=$('#collage-layout').value,gap=+$('#collage-gap').value,n=collage.length;const cols=layout==='strip'?1:layout==='diptych'?Math.max(n,1):Math.min(n,2)||1,rows=Math.ceil(n/cols)||1;c.width=1200;c.height=layout==='strip'?Math.max(1,n)*650:layout==='diptych'?700:1200;ctx.fillStyle=$('#collage-color').value;ctx.fillRect(0,0,c.width,c.height);const w=(c.width-gap*(cols+1))/cols,h=(c.height-gap*(rows+1))/rows;collage.forEach(({img},i)=>{const r=Math.max(w/img.width,h/img.height),sw=w/r,sh=h/r;ctx.drawImage(img,(img.width-sw)/2,(img.height-sh)/2,sw,sh,gap+(i%cols)*(w+gap),gap+Math.floor(i/cols)*(h+gap),w,h);});$('#collage-hint').hidden=n>0;$('#collage-items').replaceChildren();collage.forEach((item,i)=>{const b=document.createElement('button'),img=document.createElement('img'),x=document.createElement('span');img.src=item.url;img.alt=`Foto ${i+1}`;x.textContent='×';b.setAttribute('aria-label',`Remover foto ${i+1}`);b.append(img,x);b.onclick=()=>{URL.revokeObjectURL(item.url);collage.splice(i,1);drawCollage();};$('#collage-items').append(b);});}
for(const id of ['collage-layout','collage-gap','collage-color'])$('#'+id).oninput=drawCollage;
$('#collage-save').onclick=async()=>{if(collage.length<2)return toast('Adicione pelo menos duas fotos.');try{await storeOutput(await blobFromCanvas($('#collage-canvas')),'photo',null,{camera:'collage'});}catch(e){fail(e);}};
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)&&!$('dialog[open]')&&!$('#camera-view').hidden){e.preventDefault();capture();}});
